function splitSteps(text){const out=[];let cur=null;for(const raw of clean(text).split("\n")){const line=raw.trim();const m=line.match(/^step\s*(\d+)\s*([^：:\n]*)(?:[：:]|$)\s*(.*)$/i);if(m){if(cur)out.push(cur);cur={n:m[1],title:clean(m[2])||"步骤 "+m[1],lines:m[3]?[m[3]]:[]}}else if(cur)cur.lines.push(raw);else if(line){cur={n:String(out.length+1),title:"前置说明",lines:[raw]}}}if(cur)out.push(cur);return out}
