function splitSections(text,labels){const map={__unparsed:""};let current="";for(const raw of clean(text).split("\n")){const normalized=raw.replace(/^\s*[-*]\s*/,"").trim();const hit=labels.find(l=>normalized===l||normalized.startsWith(l+"：")||normalized.startsWith(l+":"));if(hit){current=hit;map[current]=normalized.slice(hit.length).replace(/^[：:]\s*/,"")}else if(current)map[current]+=(map[current]?"\n":"")+raw.trim();else if(raw.trim())map.__unparsed+=(map.__unparsed?"\n":"")+raw.trim()}return map}
function band(title,text,cls=""){const s=node("section","pt-band "+cls);s.append(node("h3","",title),node("p","pt-text",clean(text)||"无"));return s}
