function renderSteps(text){const f=document.createDocumentFragment();const steps=splitSteps(text);if(!steps.length)return empty();steps.forEach((s,i)=>{const box=node("section","pt-disclosure");box.dataset.open=i===0?"true":"false";const id="pt-step-"+state.page+"-"+i;const toggle=node("button","pt-disclosure-toggle");toggle.type="button";toggle.dataset.action="toggle-step";toggle.setAttribute("aria-expanded",i===0?"true":"false");toggle.setAttribute("aria-controls",id);toggle.append(node("span","pt-step-num","STEP "+s.n),node("span","",s.title||"步骤 "+s.n),node("span","pt-disclosure-arrow","›"));const grid=node("div","pt-disclosure-grid");grid.id=id;const inner=node("div","pt-disclosure-inner");inner.append(node("div","pt-disclosure-body",clean(s.lines.join("\n"))||"无补充内容"));grid.append(inner);box.append(toggle,grid);f.append(box)});return f}
function renderRecall(text,tone="ok"){const source=clean(text);if(!source||/^无(?:相关)?/.test(source))return empty(source||"当前没有召回记录");const f=document.createDocumentFragment();const ids=source.split(/\s+/).map(x=>x.trim()).filter(Boolean);f.append(band("召回数量",ids.length+" 条"));const grid=node("div","pt-grid-4");for(const id of ids){const c=node("div","pt-chip",id);c.dataset.tone=tone;grid.append(c)}f.append(grid);return f}
function renderTimeline(text){const rows=clean(text).split("\n").map(x=>x.trim()).filter(Boolean);if(!rows.length||rows[0]==="无")return empty("本轮没有相关原著时间线");const parsed=rows.map(line=>line.split("｜").map(clean));if(parsed.some(parts=>parts.length!==4||parts.some(x=>!x)))return parseError("时间线格式异常，已保留完整原文。",text);const table=node("table","pt-timeline");const head=node("thead");const hr=node("tr");for(const h of ["标识","相对时间","原著事件","命中原因"])hr.append(node("th","",h));head.append(hr);const body=node("tbody");for(const parts of parsed){const tr=node("tr");["标识","相对时间","原著事件","命中原因"].forEach((label,i)=>{const td=node("td","",parts[i]);td.dataset.label=label;tr.append(td)});body.append(tr)}table.append(head,body);return table}
function renderClue(text){const fields=parseFields(text);const required=["当前主身份","场景锚点","候选人物","候选设定关键词","依据来源"];const map=new Map(fields.map(x=>[x.key,x.value]));if(required.some(key=>!map.has(key)))return parseError("场景线索字段不完整，已保留完整原文。",text);const grid=node("div","pt-grid");for(const key of required)grid.append(keyValue(key,map.get(key)));return grid}
function parsePeopleBlocks(text){const blocks=[];const re=/^###?\s*\[?([^\]\n]+)\]?\s*$/gm;let m;const hits=[];while((m=re.exec(clean(text))))hits.push({name:clean(m[1]),start:m.index,end:re.lastIndex});if(!hits.length){const bracket=/^\[([^\]\n]+)\]\s*$/gm;while((m=bracket.exec(clean(text))))hits.push({name:clean(m[1]),start:m.index,end:bracket.lastIndex})}hits.forEach((h,i)=>blocks.push({name:h.name,text:clean(text).slice(h.end,hits[i+1]?.start??clean(text).length).trim()}));return blocks}
function personLayout(blocks,renderer,key){if(!blocks.length)return empty();const wrap=node("div","pt-person-layout");const tabs=node("div","pt-person-tabs");tabs.setAttribute("role","tablist");tabs.setAttribute("aria-label","人物选择");const body=node("div","pt-person-body");body.id="pt-person-panel-"+key;body.setAttribute("role","tabpanel");const selected=Math.min(state.person[key]||0,blocks.length-1);blocks.forEach((b,i)=>{const btn=node("button","",b.name);btn.type="button";btn.id="pt-person-tab-"+key+"-"+i;btn.setAttribute("role","tab");btn.setAttribute("aria-selected",i===selected?"true":"false");btn.setAttribute("aria-controls",body.id);btn.tabIndex=i===selected?0:-1;btn.dataset.personIndex=String(i);btn.dataset.personKey=key;tabs.append(btn)});body.setAttribute("aria-labelledby","pt-person-tab-"+key+"-"+selected);body.append(renderer(blocks[selected]));wrap.append(tabs,body);return wrap}
