function matrixTable(title,text,columns){const section=node("section","pt-band");section.append(node("h3","",title));const rows=new Map();for(const raw of clean(text).split("\n")){const line=raw.replace(/^\s*[-*]\s*/,"").trim();for(const col of columns){const marker=line.indexOf(col);if(marker<1)continue;const left=line.slice(0,marker).replace(/^\[|\]$/g,"").trim();const rest=line.slice(marker+col.length).replace(/^[：:]\s*/,"");if(!left)continue;if(!rows.has(left))rows.set(left,{});rows.get(left)[col]=rest;break}}if(!rows.size){section.append(node("p","pt-text",clean(text)||"无"));return section}const table=node("table","pt-audit-table");const thead=node("thead");const tr=node("tr");tr.append(node("th","","人物/职责角色"));columns.forEach(c=>tr.append(node("th","",c)));thead.append(tr);const tbody=node("tbody");for(const [name,values] of rows){const row=node("tr");const nameCell=node("td","",name);nameCell.dataset.label="人物/职责角色";row.append(nameCell);columns.forEach(c=>{const cell=node("td","",values[c]||"无");cell.dataset.label=c;row.append(cell)});tbody.append(row)}table.append(thead,tbody);section.append(table);return section}
